//
//  BespokeMapGeography.swift
//  EusoTrip — REAL (simplified) geographic boundaries for BespokeMapCanvas.
//
//  WHY THIS EXISTS (founder mandate 2026-06-21): the bespoke route map read as
//  "just a line to and from" — no states, no cities, no road indication. The
//  abstract continent rings in BespokeMapBasemap give only coastline blobs.
//  This file adds surveyed-but-simplified vector geography that projects through
//  the SAME Web-Mercator BespokeMapViewport as the route/markers, so every map
//  gains real geographic context with NO tiles, NO WKWebView, NO network —
//  consistent with the HERE-native-map-engine + bespoke-cartography doctrine.
//
//  DATA PROVENANCE (public domain): US states from the canonical Leaflet
//  us-states GeoJSON; Canada provinces + world coastlines from Natural Earth
//  (admin-1 50m / admin-0 110m). Each polygon was Douglas-Peucker-simplified
//  (states ~0.03°, provinces ~0.09°, world ~0.55°) and outer-ring-only. Major
//  metros + interstate freight corridors are hand-curated.
//
//  ENCODING: boundary geometry is stored as compact ENCODED STRINGS parsed once
//  at first access (cached) — NOT Swift array literals. ~9k coordinate pairs as
//  a [(Double,Double)] literal would detonate the Swift type-checker; a string
//  literal compiles instantly and parses in <5ms. Format:
//     feature = "NAME~ABBR~ring|ring"   (features separated by newline)
//     ring    = "lng,lat lng,lat ..."   (4-decimal fixed)
//
//  Powered by ESANG AI™.
//

import CoreGraphics

enum BespokeMapGeography {

    /// A parsed boundary feature: one or more outer rings in (lng, lat) degrees,
    /// plus a label anchor (centroid of the largest ring) and bbox span (degrees)
    /// used to gate label/border visibility by zoom.
    struct Feature {
        let name: String
        let abbrev: String
        let rings: [[(lng: Double, lat: Double)]]
        let labelAnchor: (lng: Double, lat: Double)
        let span: Double
    }

    /// A labeled place (city/metro) for the place-label layer.
    struct Place {
        let name: String
        let lat: Double
        let lng: Double
        let rank: Int      // 1 = primary (always shown), 3 = secondary (high zoom only)
        init(_ name: String, _ lat: Double, _ lng: Double, _ rank: Int) {
            self.name = name; self.lat = lat; self.lng = lng; self.rank = rank
        }
    }

    /// A named road corridor (interstate) as an ordered (lng, lat) polyline.
    struct Corridor {
        let name: String
        let path: [(lng: Double, lat: Double)]
    }

