    // MARK: - Parsers

    static func parseFeatures(_ s: String) -> [Feature] {
        var out: [Feature] = []
        for lineSub in s.split(separator: "\n") {
            let parts = lineSub.split(separator: "~", maxSplits: 2, omittingEmptySubsequences: false)
            guard parts.count == 3 else { continue }
            let name = String(parts[0])
            let abbr = String(parts[1])
            var rings: [[(lng: Double, lat: Double)]] = []
            var minLng = 1e9, minLat = 1e9, maxLng = -1e9, maxLat = -1e9
            var bestRing: [(lng: Double, lat: Double)] = []
            for ringSub in parts[2].split(separator: "|") {
                var ring: [(lng: Double, lat: Double)] = []
                for pairSub in ringSub.split(separator: " ") {
                    let xy = pairSub.split(separator: ",")
                    guard xy.count == 2,
                          let rawLng = Double(xy[0]),
                          let rawLat = Double(xy[1]),
                          let coordinate = LatLongParser.validatedCoordinate(
                            latitude: rawLat,
                            longitude: rawLng
                          ) else { continue }
                    let lng = coordinate.longitude
                    let lat = coordinate.latitude
                    ring.append((lng, lat))
                    if lng < minLng { minLng = lng }; if lng > maxLng { maxLng = lng }
                    if lat < minLat { minLat = lat }; if lat > maxLat { maxLat = lat }
                }
                if ring.count >= 3 {
                    rings.append(ring)
                    if ring.count > bestRing.count { bestRing = ring }
                }
            }
            guard !rings.isEmpty else { continue }
            // Label anchor = average of the largest ring (lands inside the main
            // landmass better than a bbox center for odd shapes).
            var ax = 0.0, ay = 0.0
            for p in bestRing { ax += p.lng; ay += p.lat }
            let anchor = (lng: ax / Double(bestRing.count), lat: ay / Double(bestRing.count))
            let span = Swift.max(maxLng - minLng, maxLat - minLat)
            out.append(Feature(name: name, abbrev: abbr, rings: rings, labelAnchor: anchor, span: span))
        }
        return out
    }

    static func parseCorridors(_ s: String) -> [Corridor] {
        var out: [Corridor] = []
        for lineSub in s.split(separator: "\n") {
            let parts = lineSub.split(separator: "~", maxSplits: 2, omittingEmptySubsequences: false)
            guard parts.count == 3 else { continue }
            var path: [(lng: Double, lat: Double)] = []
            for pairSub in parts[2].split(separator: " ") {
                let xy = pairSub.split(separator: ",")
                guard xy.count == 2,
                      let rawLng = Double(xy[0]),
                      let rawLat = Double(xy[1]),
                      let coordinate = LatLongParser.validatedCoordinate(
                        latitude: rawLat,
                        longitude: rawLng
                      ) else { continue }
                path.append((coordinate.longitude, coordinate.latitude))
            }
            if path.count >= 2 { out.append(Corridor(name: String(parts[0]), path: path)) }
        }
        return out
    }

